    ["Chizhou"] = "Чичжоу",
    ["<Assistant_Title1>【Lightning Lily】</>\n<Assistant_Title2>Quest Type:</><Assistant_Property2>Life in the Era</>\n<Assistant_Title2>Quest Description:</>A legendary delivery person has appeared in Tingen—Lightning Lily, whose speed is unimaginably fast!\n<Assistant_Title2>How to Accept:</>After reaching <Assistant_Red>Level 61</> in Acting, head to {Location:[Tingen(808,1125)]|-18931;12326;-1979;2;5200002;0} to trigger the quest.\n<Assistant_Title2>Quest Rewards:</>Cognition EXP, Bound Soule, Invoices, Adventure Medals, World Adventure Treasure progress."] = "<Assistant_Title1>【Молниеносная Лилия】</>\n<Assistant_Title2>Тип миссии: </><Assistant_Property2>Разнообразие времен</>\n<Assistant_Title2>Описание миссии: </>В Тингене появляется легендарный доставщик-Молниеносная Лилия, скорость невообразимая! \n<Assistant_Title2>Как получить: </>После того, как уровень роли достигнет <Assistant_Red>61</>, перейдите в {Location:[Tinggen(808,1125)]|-18931 ;12326;-1979;2;5200002;0} Можно запускать задачи \n<Assistant_Title2>Task Награды</>: познавательный опыт, переплет Суле, счета-фактуры, медали приключений, прогресс в секретных сокровищах мировых приключений.",
    ["<Assistant_Title1>Undying Power</>\n<Assistant_Title2>Achievement Category: </>Plot - Reality Main Story\n<Assistant_Title2>Unlock Condition: </>In the prologue main story, awaken Undying Power and defeat the Moon Corruption."] = "<Assistant_Title1>Немеркнущая сила</>\n<Assistant_Title2>Категория достижения: </>Сюжет — Реальность (основной)\n<Assistant_Title2>Условие получения: </>В прологе основного сюжета пробудите Немеркнущую силу и одолейте осквернение Луны.",
    ["Bring the potion to everyone"] = "Принеси зелье всем",
    ["Do you want to create a new character?"] = "Хотите создать нового персонажа?",
    ["tShipwreck"] = "tКораблекрушение",
    ["Light that dispels darkness descends amidst praise."] = "Свет, рассеивающий тьму, нисходит среди хвалы.",
    ["A defensive<Highlight> mutated material</> with the entry <Highlight><The Unshadowed></>: \"Increased Willpower.\""] = "Защитный <Highlight> изменил материал </> с записью <Highlight><The Unshadowed></>: «Увеличенная сила воли».",
    ["Level 3 - Insight"] = "Уровень 3 – Проницательность",
